using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalTests
{
    private static DistributedApplicationTestingBuilder _appBuilder = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;

    private static readonly ReportingConfiguration s_reporting = CreateReportingConfiguration();

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appBuilder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appBuilder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_RespondsCoherently()
    {
        await using var scenario = await s_reporting.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_RespondsCoherently));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France? Answer in one sentence.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_FollowsInstructions()
    {
        await using var scenario = await s_reporting.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_FollowsInstructions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in exactly three bullet points."),
            new(ChatRole.User, "What are the benefits of exercise?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_HandlesMultiTurn()
    {
        await using var scenario = await s_reporting.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_HandlesMultiTurn));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Remember the number 42.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "What number did I ask you to remember?"));

        response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages);
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
        };

        var storagePath = Path.Combine(
            Path.GetDirectoryName(typeof(EvalTests).Assembly.Location)!,
            "eval-results");

        return DiskBasedReportingConfiguration.Create(storagePath, evaluators);
    }
}

